package com.kovian.finance.liability.api; import com.kovian.finance.liability.domain.*; import com.kovian.finance.liability.repository.*; import com.kovian.finance.security.CurrentUser; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/v1/liabilities") public class LiabilityController {final FinancialLiabilityRepository repo; LiabilityController(FinancialLiabilityRepository r){repo=r;} record Request(UUID ownerId,String name,String liabilityType,BigDecimal amount){} @PostMapping public FinancialLiability create(@RequestBody Request r){UUID owner=CurrentUser.ownerId(); if(r.ownerId()!=null&&!owner.equals(r.ownerId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation"); if(r.name()==null||r.name().isBlank()||r.amount()==null||r.amount().signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid liability request"); return repo.save(new FinancialLiability(owner,r.name(),r.liabilityType(),r.amount()));} @GetMapping public List<FinancialLiability> list(@RequestParam(required=false) UUID ownerId){UUID owner=CurrentUser.ownerId(); if(ownerId!=null&&!owner.equals(ownerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation"); return repo.findByOwnerIdAndActiveTrue(owner);} @PatchMapping("/{id}") public void update(@PathVariable UUID id,@RequestParam(required=false) UUID ownerId,@RequestBody BigDecimal amount){UUID owner=CurrentUser.ownerId(); if(ownerId!=null&&!owner.equals(ownerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation"); repo.findById(id).filter(x->x.getOwnerId().equals(owner)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Liability not found")).updateAmount(amount);}}